-- ==========================================
-- PRECIOUS.UZ SUPABASE SCHEMA & SEED SCRIPT
-- Run this script in your Supabase SQL Editor
-- ==========================================

-- 1. Create 'products' table
create table if not exists public.products (
  id text primary key,
  category text not null,
  model text not null,
  image_url text not null default '',
  tagline jsonb not null default '{}'::jsonb,
  description jsonb not null default '{}'::jsonb,
  specs jsonb not null default '[]'::jsonb,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  updated_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 2. Enable Row Level Security (RLS)
alter table public.products enable row level security;

-- 3. RLS Policies & Grants for 'products' table
grant select on public.products to anon, authenticated;
grant insert, update, delete on public.products to authenticated;

drop policy if exists "Allow public read access" on public.products;
create policy "Allow public read access" on public.products
  for select using (true);

drop policy if exists "Allow authenticated admin write access" on public.products;
create policy "Allow authenticated admin write access" on public.products
  for all using (auth.role() = 'authenticated');

-- 4. Create Storage Bucket 'product-images' if not exists
insert into storage.buckets (id, name, public)
values ('product-images', 'product-images', true)
on conflict (id) do update set public = true;

-- 5. Storage RLS Policies
drop policy if exists "Public access for product images" on storage.objects;
create policy "Public access for product images" on storage.objects
  for select using (bucket_id = 'product-images');

drop policy if exists "Admin upload access for product images" on storage.objects;
create policy "Admin upload access for product images" on storage.objects
  for insert with check (bucket_id = 'product-images' and auth.role() = 'authenticated');

drop policy if exists "Admin update access for product images" on storage.objects;
create policy "Admin update access for product images" on storage.objects
  for update using (bucket_id = 'product-images' and auth.role() = 'authenticated');

drop policy if exists "Admin delete access for product images" on storage.objects;
create policy "Admin delete access for product images" on storage.objects
  for delete using (bucket_id = 'product-images' and auth.role() = 'authenticated');

-- 6. Insert 36 initial products
insert into public.products (id, category, model, image_url, tagline, description, specs)
values
('pc9893d', 'lockstitch', 'PC9893D', '', '{"uz":"Yuqori tezlikli bir ignali to''g''ri chok mashinasi","ru":"Высокоскоростная одноигольная прямострочная машина","en":"High-speed single-needle lockstitch machine"}'::jsonb, '{"uz":"Yengil va o''rta qalinlikdagi matolar uchun mo''ljallangan yuqori tezlikdagi bir ignali to''g''ri chokli sanoat tikuv mashinasi. Aniq, tekis va barqaror chok hosil qiladi, servo motor esa kam shovqin va tejamkor energiya sarfini ta''minlaydi. PRECIOUS''ning eng ko''p tanlanadigan bestseller modellaridan biri.","ru":"Высокоскоростная одноигольная прямострочная машина для лёгких и средних тканей. Обеспечивает точную, ровную и стабильную строчку, а сервомотор — низкий уровень шума и экономичный расход энергии. Один из самых популярных бестселлеров PRECIOUS.","en":"A high-speed single-needle lockstitch machine for light and medium-weight fabrics. It produces a precise, even, stable stitch, while the servo motor keeps noise low and power use efficient. One of PRECIOUS''s best-selling models."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Tikuv turi","ru":"Тип строчки","en":"Stitch type"},"value":{"uz":"bir qatorli to''g''ri chok","ru":"однорядная прямая строчка","en":"single-row lockstitch"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"5 mm gacha","ru":"до 5 мм","en":"up to 5 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"5000 chok/daqiqa","ru":"5000 стежков/мин","en":"5000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DB×1","ru":"DB×1","en":"DB×1"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('g18d', 'lockstitch', 'G18D', '', '{"uz":"Panelli boshqaruvga ega to''g''ri chok mashinasi","ru":"Прямострочная машина с панелью управления","en":"Lockstitch machine with control panel"}'::jsonb, '{"uz":"Panelli boshqaruvga ega bir ignali to''g''ri chokli sanoat tikuv mashinasi. Yengil va o''rta qalinlikdagi matolar bilan ishlash uchun mo''ljallangan bestseller model — boshqaruv paneli ish jarayonini qulay va oson nazorat qilish imkonini beradi. Yuqori tikuv tezligi unumdorlikni oshiradi, servo motor esa kam shovqinli va energiya tejamkor ishlashni ta''minlaydi.","ru":"Одноигольная прямострочная машина с панелью управления для лёгких и средних тканей. Панель управления делает рабочий процесс удобным и простым, а высокая скорость шитья повышает производительность. Сервомотор обеспечивает низкий уровень шума и экономию энергии.","en":"A single-needle lockstitch machine with a control panel, built for light and medium-weight fabrics. The panel makes the workflow convenient to monitor, and high sewing speed boosts output. The servo motor keeps it quiet and energy-efficient."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Tikuv turi","ru":"Тип строчки","en":"Stitch type"},"value":{"uz":"bir qatorli to''g''ri chok","ru":"однорядная прямая строчка","en":"single-row lockstitch"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"5 mm gacha","ru":"до 5 мм","en":"up to 5 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"5000 chok/daqiqa","ru":"5000 стежков/мин","en":"5000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DB×1","ru":"DB×1","en":"DB×1"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('g18-d1', 'lockstitch', 'G18-D1', '', '{"uz":"Avtomatik ip kesuvchili to''g''ri chok mashinasi","ru":"Прямострочная машина с автообрезкой нити","en":"Lockstitch machine with automatic thread trimmer"}'::jsonb, '{"uz":"Avtomatik ip kesish funksiyasiga ega bir ignali to''g''ri chokli bestseller model. Yengil va o''rta qalinlikdagi matolar bilan ishlash uchun mo''ljallangan, avtomatik ip kesish tikuv jarayonini tezlashtirib, ortiqcha qo''l mehnatini kamaytiradi. Servo motor kam shovqinli, barqaror va energiya tejamkor ishlashni ta''minlaydi.","ru":"Бестселлер среди одноигольных прямострочных машин с функцией автоматической обрезки нити. Автообрезка ускоряет процесс шитья и снижает ручной труд оператора. Сервомотор обеспечивает стабильную, тихую и энергоэффективную работу.","en":"A best-selling single-needle lockstitch machine with automatic thread trimming. The auto-trim speeds up the sewing process and reduces manual work. The servo motor delivers stable, quiet, energy-efficient operation."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Avtomatik ip kesish","ru":"Автообрезка нити","en":"Automatic thread trimming"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Tikuv turi","ru":"Тип строчки","en":"Stitch type"},"value":{"uz":"bir qatorli to''g''ri chok","ru":"однорядная прямая строчка","en":"single-row lockstitch"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"5 mm gacha","ru":"до 5 мм","en":"up to 5 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"5000 chok/daqiqa","ru":"5000 стежков/мин","en":"5000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DB×5","ru":"DB×5","en":"DB×5"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('g18-d4', 'lockstitch', 'G18-D4', '', '{"uz":"To''liq avtomatik funksiyali to''g''ri chok mashinasi","ru":"Прямострочная машина с полным набором автофункций","en":"Lockstitch machine with full automatic functions"}'::jsonb, '{"uz":"Avtomatik funksiyalarga ega bir ignali to''g''ri chokli bestseller model. Avtomatik ip kesish, tepki ko''tarish va chokni mustahkamlash funksiyalari tikuv jarayonini tezlashtirib, ishni yanada qulay qiladi. Yuqori tikuv tezligi va servo motor barqaror hamda energiya tejamkor ishlashni ta''minlaydi.","ru":"Одноигольная прямострочная машина с полным набором автофункций. Автообрезка нити, автоподъём лапки и автозакрепка стежка ускоряют работу и делают её удобнее. Высокая скорость шитья и сервомотор обеспечивают стабильную, экономичную работу.","en":"A single-needle lockstitch machine with a full set of automatic functions. Automatic thread trimming, presser-foot lift and stitch back-tacking speed up the workflow and make it more convenient. High sewing speed and the servo motor keep it stable and energy-efficient."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Avtomatik ip kesish","ru":"Автообрезка нити","en":"Automatic thread trimming"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Avtomatik tepki ko''tarish","ru":"Автоподъём лапки","en":"Automatic presser-foot lift"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Avtomatik chokni mustahkamlash","ru":"Автозакрепка стежка","en":"Automatic back-tacking"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"5 mm gacha","ru":"до 5 мм","en":"up to 5 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"5000 chok/daqiqa","ru":"5000 стежков/мин","en":"5000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DB×1","ru":"DB×1","en":"DB×1"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('g18e', 'lockstitch', 'G18E', '', '{"uz":"Step motorli avtomatik to''g''ri chok mashinasi","ru":"Автоматическая прямострочная машина с шаговым двигателем","en":"Automatic lockstitch machine with stepping motor"}'::jsonb, '{"uz":"Step motorli avtomatik bir ignali to''g''ri chokli zamonaviy model. Avtomatik ip kesish, tepki ko''tarish va chokni mustahkamlash funksiyalari ish jarayonini tez va qulay tashkil etishga yordam beradi. 9 xil dekorativ chok imkoniyati qo''shimcha qulaylik yaratadi, step motor esa aniq va barqaror ishlashni ta''minlaydi.","ru":"Современная автоматическая одноигольная прямострочная машина на шаговом двигателе. Автообрезка нити, автоподъём лапки и автозакрепка ускоряют и упрощают процесс шитья. 9 видов декоративных строчек добавляют гибкости, а шаговый двигатель обеспечивает точность и стабильность.","en":"A modern automatic single-needle lockstitch machine driven by a stepping motor. Automatic thread trimming, presser-foot lift and back-tacking make the workflow fast and convenient. 9 decorative stitch patterns add flexibility, while the stepping motor keeps it precise and stable."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Avtomatik ip kesish","ru":"Автообрезка нити","en":"Automatic thread trimming"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Avtomatik tepki ko''tarish","ru":"Автоподъём лапки","en":"Automatic presser-foot lift"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Avtomatik chokni mustahkamlash","ru":"Автозакрепка стежка","en":"Automatic back-tacking"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Dekorativ choklar","ru":"Декоративные строчки","en":"Decorative stitches"},"value":{"uz":"9 xil","ru":"9 видов","en":"9 patterns"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"5 mm gacha","ru":"до 5 мм","en":"up to 5 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"5000 chok/daqiqa","ru":"5000 стежков/мин","en":"5000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DB×1","ru":"DB×1","en":"DB×1"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"step motor","ru":"шаговый двигатель","en":"stepping motor"}}]'::jsonb),
('g21-2', 'lockstitch', 'G21-2', '', '{"uz":"Sensorli boshqaruvga ega ikki step motorli mashina","ru":"Машина с сенсорным управлением и двумя шаговыми двигателями","en":"Sensor-controlled machine with dual stepping motors"}'::jsonb, '{"uz":"2 ta step motor va sensorli boshqaruvga ega avtomatik bir ignali to''g''ri chokli zamonaviy model. Sensorli boshqaruv tizimi tikuv jarayonida yuqori aniqlik, barqarorlik va qulay boshqaruvni ta''minlaydi. Avtomatik ip kesish, tepki ko''tarish va chokni mustahkamlash funksiyalari, shuningdek 9 xil dekorativ chok imkoniyati mavjud.","ru":"Современная автоматическая одноигольная прямострочная машина с двумя шаговыми двигателями и сенсорным управлением. Сенсорная система обеспечивает высокую точность, стабильность и удобство в работе. Есть автообрезка нити, автоподъём лапки, автозакрепка и 9 видов декоративных строчек.","en":"A modern automatic single-needle lockstitch machine with two stepping motors and sensor-based control for high precision, stability and ease of use. It includes automatic thread trimming, presser-foot lift, back-tacking, and 9 decorative stitch patterns."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Step motorlar soni","ru":"Количество шаговых двигателей","en":"Stepping motors"},"value":{"uz":"2 ta","ru":"2","en":"2"}},{"label":{"uz":"Boshqaruv turi","ru":"Тип управления","en":"Control type"},"value":{"uz":"sensorli","ru":"сенсорное","en":"sensor-based"}},{"label":{"uz":"Avtomatik ip kesish","ru":"Автообрезка нити","en":"Automatic thread trimming"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Avtomatik tepki ko''tarish","ru":"Автоподъём лапки","en":"Automatic presser-foot lift"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Avtomatik chokni mustahkamlash","ru":"Автозакрепка стежка","en":"Automatic back-tacking"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Dekorativ choklar","ru":"Декоративные строчки","en":"Decorative stitches"},"value":{"uz":"9 xil","ru":"9 видов","en":"9 patterns"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"5 mm gacha","ru":"до 5 мм","en":"up to 5 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"5000 chok/daqiqa","ru":"5000 стежков/мин","en":"5000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DB×1","ru":"DB×1","en":"DB×1"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"step motor","ru":"шаговый двигатель","en":"stepping motor"}}]'::jsonb),
('v19-4', 'overlock', 'V19-4', '', '{"uz":"4 ipli sanoat overlok mashinasi","ru":"4-ниточная промышленная оверлочная машина","en":"4-thread industrial overlock machine"}'::jsonb, '{"uz":"4 ipli sanoat overlok bestseller modeli, yengil va o''rta qalinlikdagi matolar bilan ishlash uchun mo''ljallangan. Overlok tizimi mato chetlarini sifatli tikish va puxta ishlov berish imkonini beradi. Yopiq moy tizimi tozalikni saqlaydi, servo motor esa barqaror va kam shovqinli ishlashni ta''minlaydi.","ru":"Бестселлер среди 4-ниточных промышленных оверлочных машин для лёгких и средних тканей. Система обеспечивает качественную обработку и обмётку края. Закрытая масляная система сохраняет чистоту, сервомотор — стабильную и тихую работу.","en":"A best-selling 4-thread industrial overlock machine for light and medium-weight fabrics. It finishes and secures fabric edges cleanly. The enclosed oil system keeps things clean, and the servo motor keeps it stable and quiet."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"2 ta","ru":"2","en":"2"}},{"label":{"uz":"Iplar soni","ru":"Количество нитей","en":"Threads"},"value":{"uz":"4 ta","ru":"4","en":"4"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"6000 chok/daqiqa","ru":"6000 стежков/мин","en":"6000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DC×27","ru":"DC×27","en":"DC×27"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}},{"label":{"uz":"Moy idishi","ru":"Масляный резервуар","en":"Oil reservoir"},"value":{"uz":"yopiq","ru":"закрытый","en":"enclosed"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"5,5 mm","ru":"5,5 мм","en":"5.5 mm"}},{"label":{"uz":"Maksimal chok uzunligi","ru":"Макс. длина стежка","en":"Max stitch length"},"value":{"uz":"3,6 mm","ru":"3,6 мм","en":"3.6 mm"}}]'::jsonb),
('v19-5', 'overlock', 'V19-5', '', '{"uz":"5 ipli sanoat overlok mashinasi","ru":"5-ниточная промышленная оверлочная машина","en":"5-thread industrial overlock machine"}'::jsonb, '{"uz":"5 ipli sanoat overlok yuqori unumdorlikdagi model, yengil va o''rta qalinlikdagi matolar bilan ishlash uchun mo''ljallangan. Overlok tizimi mato chetlarini tikish, mustahkamlash va sifatli ishlov berish imkonini beradi. Yopiq moy tizimi va servo motor barqaror, kam shovqinli hamda samarali ishlashni ta''minlaydi.","ru":"Высокопроизводительная 5-ниточная промышленная оверлочная машина для лёгких и средних тканей. Система обмётывает, укрепляет и качественно обрабатывает край ткани. Закрытая масляная система и сервомотор обеспечивают стабильную, тихую и эффективную работу.","en":"A high-output 5-thread industrial overlock machine for light and medium-weight fabrics. It overedges, reinforces and finishes fabric edges with quality. The enclosed oil system and servo motor keep it stable, quiet and efficient."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"2 ta","ru":"2","en":"2"}},{"label":{"uz":"Iplar soni","ru":"Количество нитей","en":"Threads"},"value":{"uz":"5 ta","ru":"5","en":"5"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"6000 chok/daqiqa","ru":"6000 стежков/мин","en":"6000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DC×27","ru":"DC×27","en":"DC×27"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}},{"label":{"uz":"Moy idishi","ru":"Масляный резервуар","en":"Oil reservoir"},"value":{"uz":"yopiq","ru":"закрытый","en":"enclosed"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"5,5 mm","ru":"5,5 мм","en":"5.5 mm"}},{"label":{"uz":"Maksimal chok uzunligi","ru":"Макс. длина стежка","en":"Max stitch length"},"value":{"uz":"3,6 mm","ru":"3,6 мм","en":"3.6 mm"}}]'::jsonb),
('v19-4u', 'overlock', 'V19-4U', '', '{"uz":"Avtomatik ip kesuvchili 4 ipli overlok mashinasi","ru":"4-ниточный оверлок с автообрезкой нити","en":"4-thread overlock with automatic thread trimmer"}'::jsonb, '{"uz":"Avtomatik ip kesish funksiyasiga ega 4 ipli sanoat overlok zamonaviy modeli. Overlok tizimi mato chetlariga sifatli va puxta ishlov berish imkonini beradi, avtomatik ip kesish esa tikuvchining ishini yengillashtiradi. Yopiq moy tizimi va servo motor barqaror, kam shovqinli ishlashni ta''minlaydi.","ru":"Современная 4-ниточная промышленная оверлочная машина с автоматической обрезкой нити. Система качественно обрабатывает край ткани, а автообрезка облегчает работу оператора. Закрытая масляная система и сервомотор — стабильность и низкий шум.","en":"A modern 4-thread industrial overlock machine with automatic thread trimming. It finishes fabric edges cleanly, while the auto-trim eases the operator''s work. The enclosed oil system and servo motor keep it stable and quiet."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"2 ta","ru":"2","en":"2"}},{"label":{"uz":"Iplar soni","ru":"Количество нитей","en":"Threads"},"value":{"uz":"4 ta","ru":"4","en":"4"}},{"label":{"uz":"Avtomatik ip kesish","ru":"Автообрезка нити","en":"Automatic thread trimming"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"6000 chok/daqiqa","ru":"6000 стежков/мин","en":"6000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DC×27","ru":"DC×27","en":"DC×27"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}},{"label":{"uz":"Moy idishi","ru":"Масляный резервуар","en":"Oil reservoir"},"value":{"uz":"yopiq","ru":"закрытый","en":"enclosed"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"5,5 mm","ru":"5,5 мм","en":"5.5 mm"}},{"label":{"uz":"Maksimal chok uzunligi","ru":"Макс. длина стежка","en":"Max stitch length"},"value":{"uz":"3,6 mm","ru":"3,6 мм","en":"3.6 mm"}}]'::jsonb),
('v19-4utpcq', 'overlock', 'V19-4UTPCQ', '', '{"uz":"Havo tozalash funksiyali to''liq avtomatik overlok","ru":"Полностью автоматический оверлок с очисткой воздухом","en":"Fully automatic overlock with air-blow cleaning"}'::jsonb, '{"uz":"Havo bilan tozalash funksiyasiga ega to''liq avtomatik sanoat overlok zamonaviy modeli. Avtomatik ip kesish va tepki ko''tarish funksiyalari operator ishini yengillashtiradi, havo bilan tozalash esa yig''iladigan mayda mato qoldiqlari va changni tozalashga yordam beradi. Intensiv ishlab chiqarish jarayonlari uchun mos.","ru":"Полностью автоматическая современная промышленная оверлочная машина с функцией очистки воздухом. Автообрезка нити и автоподъём лапки облегчают работу оператора, а обдув воздухом удаляет мелкие обрезки ткани и пыль. Подходит для интенсивного производства.","en":"A fully automatic modern industrial overlock machine with air-blow cleaning. Automatic thread trimming and presser-foot lift ease the operator''s work, while the air-blow clears away fabric lint and dust. Suited to intensive production."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"2 ta","ru":"2","en":"2"}},{"label":{"uz":"Avtomatik ip kesish","ru":"Автообрезка нити","en":"Automatic thread trimming"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Avtomatik tepki ko''tarish","ru":"Автоподъём лапки","en":"Automatic presser-foot lift"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Havo bilan tozalash funksiyasi","ru":"Функция очистки воздухом","en":"Air-blow cleaning function"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"6000 chok/daqiqa","ru":"6000 стежков/мин","en":"6000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DC×27","ru":"DC×27","en":"DC×27"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}},{"label":{"uz":"Moy idishi","ru":"Масляный резервуар","en":"Oil reservoir"},"value":{"uz":"yopiq","ru":"закрытый","en":"enclosed"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"5,5 mm","ru":"5,5 мм","en":"5.5 mm"}},{"label":{"uz":"Maksimal chok uzunligi","ru":"Макс. длина стежка","en":"Max stitch length"},"value":{"uz":"3,6 mm","ru":"3,6 мм","en":"3.6 mm"}}]'::jsonb),
('v21-4', 'overlock', 'V21-4', '', '{"uz":"PEGASUS turidagi 4 ipli overlok mashinasi","ru":"4-ниточный оверлок типа PEGASUS","en":"PEGASUS-type 4-thread overlock machine"}'::jsonb, '{"uz":"PEGASUS turidagi 4 ipli sanoat overlok yuqori unumdorlikdagi modeli, yengil va o''rta qalinlikdagi matolar bilan ishlash uchun mo''ljallangan. PEGASUS turidagi konstruksiya mato chetlariga sifatli, tekis va puxta ishlov berish imkonini beradi. Yopiq moy tizimi va servo motor barqaror ishlashni ta''minlaydi.","ru":"Высокопроизводительная 4-ниточная промышленная оверлочная машина типа PEGASUS для лёгких и средних тканей. Конструкция типа PEGASUS даёт качественную, ровную и плотную обработку края. Закрытая масляная система и сервомотор — стабильная работа.","en":"A high-output PEGASUS-type 4-thread industrial overlock machine for light and medium-weight fabrics. The PEGASUS-type build gives a clean, even, secure edge finish. The enclosed oil system and servo motor keep it stable."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"2 ta","ru":"2","en":"2"}},{"label":{"uz":"Iplar soni","ru":"Количество нитей","en":"Threads"},"value":{"uz":"4 ta","ru":"4","en":"4"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"6000 chok/daqiqa","ru":"6000 стежков/мин","en":"6000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DC×27","ru":"DC×27","en":"DC×27"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}},{"label":{"uz":"Moy idishi","ru":"Масляный резервуар","en":"Oil reservoir"},"value":{"uz":"yopiq","ru":"закрытый","en":"enclosed"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"5,5 mm","ru":"5,5 мм","en":"5.5 mm"}},{"label":{"uz":"Maksimal chok uzunligi","ru":"Макс. длина стежка","en":"Max stitch length"},"value":{"uz":"3,6 mm","ru":"3,6 мм","en":"3.6 mm"}}]'::jsonb),
('v21-4ut', 'overlock', 'V21-4UT', '', '{"uz":"Avtomatik ip kesuvchili PEGASUS overlok mashinasi","ru":"Оверлок PEGASUS с автообрезкой нити","en":"PEGASUS-type overlock with automatic thread trimmer"}'::jsonb, '{"uz":"Avtomatik ip kesish funksiyasiga ega PEGASUS turidagi 4 ipli sanoat overlok zamonaviy modeli. Overlok tizimi mato chetlariga tekis, sifatli va puxta ishlov berish imkonini beradi. Avtomatik ip kesish va tepki ko''tarish funksiyalari operator uchun qo''shimcha qulaylik yaratadi.","ru":"Современная 4-ниточная промышленная оверлочная машина PEGASUS с автоматической обрезкой нити. Система даёт ровную, качественную и плотную обработку края. Автообрезка нити и автоподъём лапки создают дополнительное удобство оператору.","en":"A modern PEGASUS-type 4-thread industrial overlock machine with automatic thread trimming. It gives an even, clean, secure edge finish. Automatic thread trimming and presser-foot lift add extra convenience for the operator."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"2 ta","ru":"2","en":"2"}},{"label":{"uz":"Iplar soni","ru":"Количество нитей","en":"Threads"},"value":{"uz":"4 ta","ru":"4","en":"4"}},{"label":{"uz":"Avtomatik ip kesish","ru":"Автообрезка нити","en":"Automatic thread trimming"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Avtomatik tepki ko''tarish","ru":"Автоподъём лапки","en":"Automatic presser-foot lift"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"6000 chok/daqiqa","ru":"6000 стежков/мин","en":"6000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DC×27","ru":"DC×27","en":"DC×27"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}},{"label":{"uz":"Moy idishi","ru":"Масляный резервуар","en":"Oil reservoir"},"value":{"uz":"yopiq","ru":"закрытый","en":"enclosed"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"5,5 mm","ru":"5,5 мм","en":"5.5 mm"}},{"label":{"uz":"Maksimal chok uzunligi","ru":"Макс. длина стежка","en":"Max stitch length"},"value":{"uz":"3,6 mm","ru":"3,6 мм","en":"3.6 mm"}}]'::jsonb),
('f21-501cb-502bb', 'interlock', 'F21-501CB/502BB', '', '{"uz":"Rashma va beyka funksiyali 3 ignali mashina","ru":"3-игольная машина с распошивальной строчкой и обвязкой","en":"3-needle coverstitch and binding combo machine"}'::jsonb, '{"uz":"Rashma va beyka funksiyalarini birlashtirgan 3 ignali sanoat tikuv mashinasi. Bitta mashinada bir nechta tikuv jarayonlarini bajarish imkoniyati ishlab chiqarish jarayonini yanada qulay va samarali tashkil etishga yordam beradi. 3 ignali tizim tekis va sifatli chok hosil qiladi, servo motor esa barqaror ishlashni ta''minlaydi.","ru":"3-игольная промышленная машина, объединяющая распошивальную строчку и обвязку края. Возможность выполнять несколько операций на одной машине делает производство удобнее и эффективнее. 3-игольная система даёт ровную, качественную строчку, сервомотор — стабильную работу.","en":"A 3-needle industrial machine combining coverstitch and edge-binding in one. Doing several operations on a single machine makes production more convenient and efficient. The 3-needle system produces an even, quality stitch, and the servo motor keeps it stable."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"3 ta","ru":"3","en":"3"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"5000 chok/daqiqa","ru":"5000 стежков/мин","en":"5000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"UY 128GAS 65–80","ru":"UY 128GAS 65–80","en":"UY 128GAS 65–80"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"5 mm","ru":"5 мм","en":"5 mm"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"1,4–4,5 mm","ru":"1,4–4,5 мм","en":"1.4–4.5 mm"}}]'::jsonb),
('pc0303dl-12', 'heavy', 'PC0303DL-12', '', '{"uz":"Yuruvchi tepkili og''ir mato mashinasi","ru":"Машина с шагающей лапкой для плотных тканей","en":"Walking-foot machine for heavy materials"}'::jsonb, '{"uz":"Yuruvchi tepkili sanoat tikuv mashinasi bestseller modeli, o''rta va og''ir matolar bilan ishlash uchun mo''ljallangan. Yuruvchi tepki mexanizmi qalin va bir necha qatlamli materiallarni bir tekis surib, aniq va sifatli tikish imkonini beradi. Mebel, sumka, charm buyumlar ishlab chiqarishda foydalanish uchun mos.","ru":"Бестселлер среди промышленных машин с шагающей лапкой для средних и тяжёлых материалов. Механизм шагающей лапки равномерно продвигает плотные многослойные материалы, обеспечивая точную и качественную строчку. Подходит для мебели, сумок и изделий из кожи.","en":"A best-selling walking-foot industrial machine for medium and heavy materials. The walking-foot mechanism feeds thick, multi-layer materials evenly for precise, quality stitching. Suited to furniture, bags and leather goods."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Tikuv maydoni","ru":"Зона шитья","en":"Sewing area"},"value":{"uz":"33 mm","ru":"33 мм","en":"33 mm"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"12 mm gacha","ru":"до 12 мм","en":"up to 12 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"o''rta va og''ir","ru":"средние и тяжёлые","en":"medium and heavy"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"2000 chok/daqiqa","ru":"2000 стежков/мин","en":"2000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DB×17","ru":"DB×17","en":"DB×17"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc781et', 'special', 'PC781ET', '', '{"uz":"Tugma iligi ochish mashinasi","ru":"Петельная машина","en":"Buttonhole machine"}'::jsonb, '{"uz":"Tugma iligi ochish uchun mo''ljallangan maxsus sanoat tikuv mashinasi. Yengil va o''rta qalinlikdagi matolarda tugma iliklarini aniq va sifatli tikadi, turli o''lchamdagi tugmalar uchun 6,4 mm dan 25,4 mm gacha uzunlikdagi iliklarni tayyorlash imkonini beradi. Kiyim-kechak ishlab chiqarish korxonalari uchun mos.","ru":"Специальная промышленная машина для обработки петель под пуговицы. Точно и качественно выполняет петли на лёгких и средних тканях, длиной от 6,4 до 25,4 мм под разные размеры пуговиц. Подходит для швейных производств.","en":"A special industrial buttonhole machine. It sews precise, quality buttonholes on light and medium-weight fabrics, from 6.4 to 25.4 mm long to fit different button sizes. Suited to garment manufacturing."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Tugma diametri","ru":"Диаметр пуговицы","en":"Button diameter"},"value":{"uz":"15 mm gacha","ru":"до 15 мм","en":"up to 15 mm"}},{"label":{"uz":"Ilik uzunligi","ru":"Длина петли","en":"Buttonhole length"},"value":{"uz":"6,4–25,4 mm","ru":"6,4–25,4 мм","en":"6.4–25.4 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"3600 chok/daqiqa","ru":"3600 стежков/мин","en":"3600 stitches/min"}},{"label":{"uz":"Igna o''lchami","ru":"Размер иглы","en":"Needle size"},"value":{"uz":"75–90","ru":"75–90","en":"75–90"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc1377e', 'special', 'PC1377E', '', '{"uz":"Tugma qadash mashinasi","ru":"Пуговичная машина","en":"Button-sewing machine"}'::jsonb, '{"uz":"Tugma qadash uchun mo''ljallangan maxsus sanoat tikuv mashinasi. Yengil va o''rta qalinlikdagi matolarga tugmalarni tez, aniq va mustahkam qadaydi, 10–28 mm diametrdagi turli o''lchamli tugmalar bilan ishlash imkonini beradi. 8, 16 va 32 ta tikuv rejimi turli ishlab chiqarish talablariga moslashadi.","ru":"Специальная промышленная машина для пришивания пуговиц. Быстро, точно и прочно пришивает пуговицы диаметром 10–28 мм на лёгких и средних тканях. Режимы на 8, 16 и 32 стежка подстраиваются под разные производственные задачи.","en":"A special industrial button-sewing machine. It sews buttons from 10–28 mm quickly, precisely and securely onto light and medium-weight fabrics. 8, 16 and 32-stitch modes adapt to different production needs."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Tugma diametri","ru":"Диаметр пуговицы","en":"Button diameter"},"value":{"uz":"10–28 mm","ru":"10–28 мм","en":"10–28 mm"}},{"label":{"uz":"Tikuvlar soni","ru":"Количество программ шитья","en":"Stitch programs"},"value":{"uz":"8, 16, 32","ru":"8, 16, 32","en":"8, 16, 32"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"1500 chok/daqiqa","ru":"1500 стежков/мин","en":"1500 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"TQ×7 №90–125","ru":"TQ×7 №90–125","en":"TQ×7 #90–125"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc20u53d', 'special', 'PC20U53D', '', '{"uz":"3 bosqichli zig-zag mashinasi","ru":"3-ступенчатая зигзаг-машина","en":"3-step zig-zag machine"}'::jsonb, '{"uz":"3 bosqichli zig-zag chokli maxsus sanoat tikuv mashinasi. Yengil va o''rta qalinlikdagi matolar bilan ishlash uchun mo''ljallangan, elastik va dekorativ choklarni sifatli hamda aniq bajaradi. 12 mm gacha zig-zag kengligi turli tikuv vazifalariga moslashish imkonini beradi.","ru":"Специальная промышленная машина с 3-ступенчатым зигзагом для лёгких и средних тканей. Качественно и точно выполняет эластичные и декоративные строчки. Ширина зигзага до 12 мм подходит для разных задач.","en":"A special industrial 3-step zig-zag machine for light and medium-weight fabrics. It sews elastic, decorative stitches with precision. A zig-zag width of up to 12 mm adapts to a range of sewing tasks."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"5 mm gacha","ru":"до 5 мм","en":"up to 5 mm"}},{"label":{"uz":"Zig-zag bosqichlari","ru":"Ступени зигзага","en":"Zig-zag steps"},"value":{"uz":"3 ta","ru":"3","en":"3"}},{"label":{"uz":"Zig-zag kengligi","ru":"Ширина зигзага","en":"Zig-zag width"},"value":{"uz":"12 mm gacha","ru":"до 12 мм","en":"up to 12 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DP×5 №75–90","ru":"DP×5 №75–90","en":"DP×5 #75–90"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc008d-12064p', 'special', 'PC008D-12064P', '', '{"uz":"12 ignali silindrsimon ko''p ignali mashina","ru":"12-игольная цилиндровая многоигольная машина","en":"12-needle cylinder-bed multi-needle machine"}'::jsonb, '{"uz":"12 ignali silindrsimon platformali sanoat tikuv mashinasi, yengil va o''rta qalinlikdagi matolar bilan ishlash uchun mo''ljallangan. 12 ignali tikuv tizimi bir vaqtning o''zida bir nechta parallel choklarni aniq bajaradi. Silindrsimon platforma aylana shaklidagi qismlarni tikishda qulaylik yaratadi.","ru":"12-игольная промышленная машина на цилиндровой платформе для лёгких и средних тканей. Система из 12 игл одновременно точно выполняет несколько параллельных строчек. Цилиндровая платформа удобна для круглых и сложных деталей.","en":"A 12-needle industrial machine on a cylinder bed, for light and medium-weight fabrics. The 12-needle system stitches several parallel rows at once with precision. The cylinder bed makes curved and complex parts easy to sew."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"12 ta","ru":"12","en":"12"}},{"label":{"uz":"Platforma turi","ru":"Тип платформы","en":"Bed type"},"value":{"uz":"silindrsimon","ru":"цилиндровая","en":"cylinder-bed"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"12 mm","ru":"12 мм","en":"12 mm"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"1,4–3,6 mm","ru":"1,4–3,6 мм","en":"1.4–3.6 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"UY113GS №75–90","ru":"UY113GS №75–90","en":"UY113GS #75–90"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc103', 'special', 'PC103', '', '{"uz":"10 dyuymli vertikal mato kesish pichog''i","ru":"10-дюймовый вертикальный раскройный нож","en":"10-inch vertical fabric cutting knife"}'::jsonb, '{"uz":"10 dyuymli, 550 W quvvatli vertikal mato kesish pichog''i. Mato qatlamlarini tez, tekis va aniq kesish uchun mo''ljallangan, 215 mm kesish balandligi bir vaqtning o''zida bir nechta qatlam bilan ishlash imkonini beradi. O''z-o''zini charxlash mexanizmi pichoqning o''tkirligini saqlashga yordam beradi.","ru":"Вертикальный раскройный нож 10 дюймов мощностью 550 Вт. Быстро, ровно и точно режет слои ткани, высота реза 215 мм позволяет работать с несколькими слоями одновременно. Механизм самозаточки сохраняет остроту лезвия.","en":"A 10-inch, 550 W vertical fabric-cutting knife. It cuts fabric layers fast, straight and precisely; a 215 mm cutting height handles multiple layers at once. A self-sharpening mechanism keeps the blade sharp."}'::jsonb, '[{"label":{"uz":"Pichoq turi","ru":"Тип ножа","en":"Blade type"},"value":{"uz":"vertikal","ru":"вертикальный","en":"vertical"}},{"label":{"uz":"Pichoq o''lchami","ru":"Размер ножа","en":"Blade size"},"value":{"uz":"10 dyuym","ru":"10 дюймов","en":"10 inches"}},{"label":{"uz":"Kesish balandligi","ru":"Высота реза","en":"Cutting height"},"value":{"uz":"215 mm","ru":"215 мм","en":"215 mm"}},{"label":{"uz":"O''z-o''zini charxlash mexanizmi","ru":"Механизм самозаточки","en":"Self-sharpening mechanism"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Dvigatel aylanish tezligi","ru":"Скорость вращения двигателя","en":"Motor speed"},"value":{"uz":"2800 ayl/daq","ru":"2800 об/мин","en":"2800 rpm"}},{"label":{"uz":"Quvvati","ru":"Мощность","en":"Power"},"value":{"uz":"550 W","ru":"550 Вт","en":"550 W"}}]'::jsonb),
('pc500', 'special', 'PC500', '', '{"uz":"Ko''rinmas chok mashinasi, stolsiz variant","ru":"Машина потайного стежка, вариант без стола","en":"Blind-stitch machine, tableless version"}'::jsonb, '{"uz":"Ko''rinmas chok uchun mo''ljallangan maxsus sanoat tikuv mashinasi, stolsiz variant. Chokning tashqi tomondan deyarli sezilmasligi kiyim va boshqa tikuv mahsulotlariga toza hamda professional ko''rinish beradi. Servo motor barqaror va energiya tejamkor ishlashni ta''minlaydi.","ru":"Специальная промышленная машина потайного стежка, вариант без стола. Практически незаметный с лицевой стороны стежок придаёт одежде аккуратный и профессиональный вид. Сервомотор обеспечивает стабильную, энергоэффективную работу.","en":"A special industrial blind-stitch machine, tableless version. A nearly invisible stitch from the outside gives garments a clean, professional finish. The servo motor keeps it stable and energy-efficient."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Tikuv turi","ru":"Тип строчки","en":"Stitch type"},"value":{"uz":"ko''rinmas chok","ru":"потайной стежок","en":"blind stitch"}},{"label":{"uz":"Komplektatsiya","ru":"Комплектация","en":"Configuration"},"value":{"uz":"stolsiz","ru":"без стола","en":"tableless"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"10 mm","ru":"10 мм","en":"10 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"2850 chok/daqiqa","ru":"2850 стежков/мин","en":"2850 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"LWx6T","ru":"LWx6T","en":"LWx6T"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc600d', 'special', 'PC600D', '', '{"uz":"Ko''rinmas chok mashinasi","ru":"Машина потайного стежка","en":"Blind-stitch machine"}'::jsonb, '{"uz":"Ko''rinmas chok hosil qilish uchun mo''ljallangan maxsus sanoat tikuv mashinasi. Tikuv matoning tashqi tomonida deyarli sezilmaydi va tayyor mahsulotga toza hamda professional ko''rinish beradi. Servo motor barqaror, kam shovqinli va energiya tejamkor ishlashni ta''minlaydi.","ru":"Специальная промышленная машина потайного стежка. Строчка практически незаметна с лицевой стороны и придаёт готовому изделию аккуратный, профессиональный вид. Сервомотор обеспечивает стабильную, тихую и энергоэффективную работу.","en":"A special industrial blind-stitch machine. The stitch is barely visible on the outside, giving the finished product a clean, professional look. The servo motor keeps it stable, quiet and energy-efficient."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Tikuv turi","ru":"Тип строчки","en":"Stitch type"},"value":{"uz":"ko''rinmas chok","ru":"потайной стежок","en":"blind stitch"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"10 mm","ru":"10 мм","en":"10 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"2000 chok/daqiqa","ru":"2000 стежков/мин","en":"2000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"GB75","ru":"GB75","en":"GB75"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc100b', 'special', 'PC100B', '', '{"uz":"Batareyali simsiz mato kesish pichog''i","ru":"Аккумуляторный беспроводной раскройный нож","en":"Cordless battery-powered fabric cutter"}'::jsonb, '{"uz":"Batareyali simsiz mato kesish uskunasi. Mato va boshqa tikuvchilik materiallarini tez, qulay va aniq kesish uchun mo''ljallangan, elektr kabeliga bog''lanmasdan erkin harakatlanish imkonini beradi. 100 mm diametrli pichoq 50 mm gacha qalinlikdagi qatlamlarni kesishga mos.","ru":"Аккумуляторный беспроводной раскройный инструмент. Быстро, удобно и точно режет ткань и другие материалы, позволяя свободно перемещаться без привязки к кабелю. Нож диаметром 100 мм режет слои толщиной до 50 мм.","en":"A cordless, battery-powered fabric-cutting tool. It cuts fabric and other materials quickly and precisely, letting the operator move freely without a power cable. A 100 mm blade cuts layers up to 50 mm thick."}'::jsonb, '[{"label":{"uz":"Pichoq diametri","ru":"Диаметр ножа","en":"Blade diameter"},"value":{"uz":"100 mm","ru":"100 мм","en":"100 mm"}},{"label":{"uz":"Kesish qalinligi","ru":"Толщина реза","en":"Cutting thickness"},"value":{"uz":"50 mm gacha","ru":"до 50 мм","en":"up to 50 mm"}},{"label":{"uz":"Aylanish tezligi","ru":"Скорость вращения","en":"Rotation speed"},"value":{"uz":"600 ayl/daq","ru":"600 об/мин","en":"600 rpm"}},{"label":{"uz":"Dvigatel quvvati","ru":"Мощность двигателя","en":"Motor power"},"value":{"uz":"255 W","ru":"255 Вт","en":"255 W"}},{"label":{"uz":"Kuchlanish","ru":"Напряжение","en":"Voltage"},"value":{"uz":"220 V","ru":"220 В","en":"220 V"}},{"label":{"uz":"Ishlash turi","ru":"Режим работы","en":"Operation mode"},"value":{"uz":"batareyali, simsiz","ru":"аккумуляторный, беспроводной","en":"battery-powered, cordless"}}]'::jsonb),
('pc100d', 'special', 'PC100D', '', '{"uz":"Diskli mato kesish pichog''i","ru":"Дисковый раскройный нож","en":"Round-blade fabric cutter"}'::jsonb, '{"uz":"Diskli mato kesish uskunasi, mato va boshqa tikuvchilik materiallarini tez, tekis va aniq kesish uchun mo''ljallangan. 100 mm diametrli disk pichoq 50 mm gacha qalinlikdagi mato qatlamlari bilan samarali ishlash imkonini beradi. Ixcham konstruksiyasi kesish jarayonini osonlashtiradi.","ru":"Дисковый раскройный инструмент для быстрого, ровного и точного раскроя ткани и других материалов. Дисковый нож диаметром 100 мм эффективно режет слои толщиной до 50 мм. Компактная конструкция упрощает процесс раскроя.","en":"A round-blade fabric-cutting tool for fast, straight and precise cutting of fabric and other materials. A 100 mm round blade efficiently cuts layers up to 50 mm thick. The compact build makes cutting easier."}'::jsonb, '[{"label":{"uz":"Pichoq diametri","ru":"Диаметр ножа","en":"Blade diameter"},"value":{"uz":"100 mm","ru":"100 мм","en":"100 mm"}},{"label":{"uz":"Kesish qalinligi","ru":"Толщина реза","en":"Cutting thickness"},"value":{"uz":"50 mm gacha","ru":"до 50 мм","en":"up to 50 mm"}},{"label":{"uz":"Aylanish tezligi","ru":"Скорость вращения","en":"Rotation speed"},"value":{"uz":"600 ayl/daq","ru":"600 об/мин","en":"600 rpm"}},{"label":{"uz":"Dvigatel quvvati","ru":"Мощность двигателя","en":"Motor power"},"value":{"uz":"255 W","ru":"255 Вт","en":"255 W"}},{"label":{"uz":"Kuchlanish","ru":"Напряжение","en":"Voltage"},"value":{"uz":"220 V","ru":"220 В","en":"220 V"}}]'::jsonb),
('pc1860a', 'special', 'PC1860A', '', '{"uz":"Chokni mustahkamlash mashinasi","ru":"Машина для закрепления шва","en":"Seam-reinforcing machine"}'::jsonb, '{"uz":"Chokning muhim qismlarini mustahkamlash uchun mo''ljallangan maxsus sanoat tikuv mashinasi. Kiyim va boshqa tikuv mahsulotlarining yuqori yuklama tushadigan qismlarida zich va mustahkam chok hosil qiladi. Yuqori ish tezligi va servo motor samaradorlikni oshiradi.","ru":"Специальная промышленная машина для закрепления ключевых участков шва. Создаёт плотный, прочный стежок на участках изделия с высокой нагрузкой. Высокая скорость и сервомотор повышают производительность.","en":"A special industrial machine for reinforcing key seam points. It produces a dense, durable stitch on high-stress areas of garments. High speed and the servo motor boost productivity."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"12 mm","ru":"12 мм","en":"12 mm"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"8–16 mm","ru":"8–16 мм","en":"8–16 mm"}},{"label":{"uz":"Maksimal tikuv kengligi","ru":"Макс. ширина стежка","en":"Max stitch width"},"value":{"uz":"1,5–3 mm","ru":"1,5–3 мм","en":"1.5–3 mm"}},{"label":{"uz":"Tikuv uzunligi","ru":"Длина строчки","en":"Stitch length (overall)"},"value":{"uz":"5 mm","ru":"5 мм","en":"5 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"2300 chok/daqiqa","ru":"2300 стежков/мин","en":"2300 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DP×5","ru":"DP×5","en":"DP×5"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc1900a', 'special', 'PC1900A', '', '{"uz":"Zamonaviy chok mustahkamlash mashinasi","ru":"Современная машина для закрепления шва","en":"Modern seam-reinforcing machine"}'::jsonb, '{"uz":"Chokning yuqori yuklama tushadigan qismlarini mustahkamlash uchun mo''ljallangan zamonaviy model. Zich va aniq mustahkamlovchi chok hosil qilib, tayyor mahsulotning chidamliligini oshirishga yordam beradi. Yuqori tikuv tezligi ishlab chiqarish jarayonini samarali tashkil etadi.","ru":"Современная модель для закрепления участков шва с высокой нагрузкой. Формирует плотный и точный закрепляющий стежок, повышая прочность готового изделия. Высокая скорость шитья делает производство эффективнее.","en":"A modern machine for reinforcing high-stress seam areas. It produces a dense, precise reinforcing stitch that boosts the finished product''s durability. High sewing speed keeps production efficient."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Tepki ko''tarilish balandligi","ru":"Высота подъёма лапки","en":"Presser-foot lift"},"value":{"uz":"12 mm","ru":"12 мм","en":"12 mm"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"8–16 mm","ru":"8–16 мм","en":"8–16 mm"}},{"label":{"uz":"Maksimal tikuv kengligi","ru":"Макс. ширина стежка","en":"Max stitch width"},"value":{"uz":"1,5–3 mm","ru":"1,5–3 мм","en":"1.5–3 mm"}},{"label":{"uz":"Tikuv uzunligi","ru":"Длина строчки","en":"Stitch length (overall)"},"value":{"uz":"5 mm","ru":"5 мм","en":"5 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"yengil va o''rta qalinlikdagi matolar","ru":"лёгкие и средние ткани","en":"light and medium-weight fabrics"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"2300 chok/daqiqa","ru":"2300 стежков/мин","en":"2300 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DP×5","ru":"DP×5","en":"DP×5"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc910', 'heavy', 'PC910', '', '{"uz":"Oyoq kiyim tikish uchun kolonkali mashina","ru":"Колонковая машина для пошива обуви","en":"Post-bed machine for footwear stitching"}'::jsonb, '{"uz":"Oyoq kiyim tikish uchun mo''ljallangan kolonkali sanoat tikuv mashinasi, o''rta va og''ir materiallar bilan ishlash uchun. Kolonkali konstruksiya murakkab shakldagi qismlarga qulay ishlov berish imkonini beradi. Rolikli tepki materialni bir tekis harakatlantirib, aniq va sifatli chok hosil qiladi.","ru":"Промышленная колонковая машина для пошива обуви, для работы со средними и тяжёлыми материалами. Колонковая конструкция удобна для деталей сложной формы. Роликовая лапка равномерно продвигает материал, обеспечивая точную и качественную строчку.","en":"A post-bed industrial machine for footwear stitching, built for medium and heavy materials. The post-bed design makes complex-shaped parts easy to work with. A roller foot feeds material evenly for a precise, quality stitch."}'::jsonb, '[{"label":{"uz":"Ignalar soni","ru":"Количество игл","en":"Needles"},"value":{"uz":"1 ta","ru":"1","en":"1"}},{"label":{"uz":"Platforma turi","ru":"Тип платформы","en":"Bed type"},"value":{"uz":"kolonkali","ru":"колонковая","en":"post-bed"}},{"label":{"uz":"Tepki turi","ru":"Тип лапки","en":"Foot type"},"value":{"uz":"rolikli","ru":"роликовая","en":"roller"}},{"label":{"uz":"Chok uzunligi","ru":"Длина стежка","en":"Stitch length"},"value":{"uz":"12 mm gacha","ru":"до 12 мм","en":"up to 12 mm"}},{"label":{"uz":"Mato turi","ru":"Тип ткани","en":"Fabric type"},"value":{"uz":"o''rta va og''ir materiallar","ru":"средние и тяжёлые материалы","en":"medium and heavy materials"}},{"label":{"uz":"Tikuv tezligi","ru":"Скорость шитья","en":"Sewing speed"},"value":{"uz":"2000 chok/daqiqa","ru":"2000 стежков/мин","en":"2000 stitches/min"}},{"label":{"uz":"Igna modeli","ru":"Модель иглы","en":"Needle system"},"value":{"uz":"DB×17","ru":"DB×17","en":"DB×17"}},{"label":{"uz":"Dvigatel turi","ru":"Тип двигателя","en":"Motor type"},"value":{"uz":"servo motor","ru":"сервомотор","en":"servo motor"}}]'::jsonb),
('pc-99b', 'special', 'PC-99B', '', '{"uz":"Bug''li sanoat dazmoli","ru":"Промышленный паровой утюг","en":"Industrial steam iron"}'::jsonb, '{"uz":"Tikuvchilik mahsulotlarini professional dazmollash va yakuniy ishlov berish uchun mo''ljallangan sanoat bug''li dazmoli. Bug'' bilan ishlash tizimi matodagi burmalarni samarali tekislab, mahsulotga saranjom ko''rinish beradi. 5 bosqichli harorat sozlagichi turli matolar uchun mos haroratni tanlash imkonini beradi.","ru":"Промышленный паровой утюг для профессиональной глажки и финишной обработки швейных изделий. Отпаривание эффективно разглаживает складки, придавая изделию аккуратный вид. Регулятор температуры на 5 ступеней подбирает режим под разные ткани.","en":"An industrial steam iron for professional finishing and pressing of sewn goods. The steam function smooths creases efficiently, giving products a neat finish. A 5-step temperature control matches the setting to different fabrics."}'::jsonb, '[{"label":{"uz":"Dazmol turi","ru":"Тип утюга","en":"Iron type"},"value":{"uz":"sanoat bug''li dazmol","ru":"промышленный паровой утюг","en":"industrial steam iron"}},{"label":{"uz":"Bug'' bilan ishlash","ru":"Отпаривание","en":"Steam function"},"value":{"uz":"mavjud","ru":"есть","en":"yes"}},{"label":{"uz":"Dazmol og''irligi","ru":"Вес утюга","en":"Iron weight"},"value":{"uz":"1,5 kg","ru":"1,5 кг","en":"1.5 kg"}},{"label":{"uz":"Quvvati","ru":"Мощность","en":"Power"},"value":{"uz":"800 W","ru":"800 Вт","en":"800 W"}},{"label":{"uz":"Harorat sozlamasi","ru":"Регулировка температуры","en":"Temperature settings"},"value":{"uz":"5 bosqichli","ru":"5 ступеней","en":"5-step"}}]'::jsonb),
